import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        // Template-based query construction for flexible reporting
        Map<String, String> params = new HashMap<>();
        params.put("table", getTableForType(reportType));
        params.put("date_filter", dateRange != null ? dateRange : "last_30_days");
        params.put("sort_column", sortCol != null ? sortCol : "created_at");
        params.put("user_id", userId != null ? userId : "ALL");

        String queryTemplate = buildQueryTemplate(reportType);
        StringSubstitutor sub = new StringSubstitutor(params);
        String finalQuery = sub.replace(queryTemplate);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"Query failed\"}");
        }
    }

    private String getTableForType(String type) {
        switch (type != null ? type : "summary") {
            case "sales": return "sales_reports";
            case "inventory": return "inventory_reports";
            case "users": return "user_activity";
            default: return "summary_reports";
        }
    }

    private String buildQueryTemplate(String type) {
        // Base template with substitution placeholders
        if ("users".equals(type)) {
            return "SELECT * FROM ${table} WHERE " +
                   "date_range = '${date_filter}' " +
                   "AND (user_id = '${user_id}' OR '${user_id}' = 'ALL') " +
                   "ORDER BY ${sort_column} LIMIT 500";
        }
        return "SELECT * FROM ${table} WHERE " +
               "date_range = '${date_filter}' " +
               "ORDER BY ${sort_column} LIMIT 1000";
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
